CREATE TYPE public.app_role AS ENUM ('student','teacher','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', campus text NOT NULL DEFAULT 'NEHU Tura Campus', department text NOT NULL DEFAULT 'Management', course text NOT NULL DEFAULT 'MBA', semester text NOT NULL DEFAULT '1', section text NOT NULL DEFAULT 'A', academic_year text NOT NULL DEFAULT '2026–2027', requested_role text NOT NULL DEFAULT 'student');
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile" ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'student',UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.on_teammaker_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); RETURN NEW; END $$;
CREATE TRIGGER teammaker_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_teammaker_signup();
CREATE TABLE public.team_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,activity_title text NOT NULL,academic_details jsonb NOT NULL DEFAULT '{}',students jsonb NOT NULL DEFAULT '[]',settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.team_sessions TO authenticated; GRANT ALL ON public.team_sessions TO service_role;
ALTER TABLE public.team_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage sessions" ON public.team_sessions FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.team_generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.team_sessions(id) ON DELETE CASCADE,teams jsonb NOT NULL,settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.team_generations TO authenticated; GRANT ALL ON public.team_generations TO service_role;
ALTER TABLE public.team_generations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read generations" ON public.team_generations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.team_sessions s WHERE s.id=session_id AND s.owner_id=auth.uid()));
CREATE TABLE public.confidential_team_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),enabled boolean NOT NULL DEFAULT true,rule_type text NOT NULL DEFAULT 'together',members jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.confidential_team_rules TO authenticated; GRANT ALL ON public.confidential_team_rules TO service_role;
ALTER TABLE public.confidential_team_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage rules" ON public.confidential_team_rules FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department text NOT NULL,course text NOT NULL,UNIQUE(department,course));
GRANT SELECT ON public.academic_options TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.academic_options TO authenticated; GRANT ALL ON public.academic_options TO service_role;
ALTER TABLE public.academic_options ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read academic options" ON public.academic_options FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admins manage options" ON public.academic_options FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.session_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.team_sessions(id) ON DELETE CASCADE,user_id uuid NOT NULL,UNIQUE(session_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.session_access TO authenticated; GRANT ALL ON public.session_access TO service_role;
ALTER TABLE public.session_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage access" ON public.session_access FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.team_sessions s WHERE s.id=session_id AND s.owner_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.team_sessions s WHERE s.id=session_id AND s.owner_id=auth.uid()));
CREATE FUNCTION public.can_read_session(_session uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.team_sessions WHERE id=_session AND owner_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.session_access WHERE session_id=_session AND user_id=auth.uid()) $$;
CREATE POLICY "Shared session read" ON public.team_sessions FOR SELECT TO authenticated USING(public.can_read_session(id));
CREATE POLICY "Shared generations read" ON public.team_generations FOR SELECT TO authenticated USING(public.can_read_session(session_id));